using UnityEditor;
using UnityEngine;
[CustomEditor(typeof(V06Card))]
public sealed class V06CardEditor:Editor
{
 V06Card Card=>(V06Card)target;
 string FoldoutKey(string section)=>"CardInspector."+Application.dataPath+"."+Card.gameObject.scene.path+"."+Card.kind+"."+section;
 bool Section(string title,bool defaultOpen){string key=FoldoutKey(title);bool open=SessionState.GetBool(key,defaultOpen);open=EditorGUILayout.Foldout(open,title,true,EditorStyles.foldoutHeader);SessionState.SetBool(key,open);return open;}
 public override void OnInspectorGUI(){serializedObject.Update();var card=Card;EditorGUILayout.LabelField(card.kind.ToString(),EditorStyles.boldLabel);
 if(Section("说明",false)){EditorGUI.indentLevel++;Draw("summary","奖励简述");if(card.GeneratedDescription)EditorGUILayout.LabelField("详细说明（读取当前配置）",card.Description(),EditorStyles.wordWrappedLabel);else Draw("details","详细说明");EditorGUILayout.LabelField("阶段效果（读取当前配置）",EditorStyles.boldLabel);string simple;if(card.TrySimpleGrowth(out simple))EditorGUILayout.LabelField(simple+"（每次获取，最多 "+card.maxPicks+" 次）",EditorStyles.wordWrappedLabel);else for(int i=1;i<=card.maxPicks;i++)EditorGUILayout.LabelField("第 "+i+" 次："+card.ShortDescription(i),EditorStyles.wordWrappedLabel);EditorGUI.indentLevel--;}
 if(Section("配置与抽取",true)){EditorGUI.indentLevel++;Draw("kind","卡牌类型");Draw("maxPicks","获取次数上限");Draw("weight","出现权重");EditorGUI.indentLevel--;}
 if(Section("效果调参",true)){EditorGUI.indentLevel++;string[] hints={"主参数：每阶段累计增加主弹数","主参数：穿透后最低伤害百分比","阶段序号1～4；分裂数量规则固定为3→2","主参数：中毒概率%；副参数：3秒总伤害%","主参数：累计射程加成%","主参数：累计普攻伤害加成%","主参数：每次暴击率增量；副参数：每次暴伤增量","主参数：攻速加成%；副参数：移速加成%"};if((int)card.kind<hints.Length)EditorGUILayout.HelpBox(hints[(int)card.kind],MessageType.Info);
 if(card.kind==V06CardKind.月牙||card.kind==V06CardKind.涟漪)DrawSword();else if(card.kind==V06CardKind.蓄势)DrawCharge();else if(card.kind==V06CardKind.踢踏舞)DrawDance();else if(card.kind==V06CardKind.写意)DrawWriting();else if(card.kind==V06CardKind.离别赠礼)DrawAfterimage();else{ Draw("values","各阶段主参数");Draw("secondary","各阶段副参数");Draw("cooldown","冷却覆盖（0沿用默认）");Draw("duration","持续时间覆盖（0沿用默认）");Draw("radius","范围覆盖（0沿用默认）");}EditorGUI.indentLevel--;}
 if(Section("装配：图标 / 音效 / 特效",true)){EditorGUI.indentLevel++;Draw("icon","卡牌图标");Draw("sound","获取音效");Draw("hitEffect","命中特效预制体");EditorGUI.indentLevel--;}
 serializedObject.ApplyModifiedProperties();
 if(Application.isPlaying){var arena=card.GetComponentInParent<ArenaPrototype>();var attack=arena?arena.v06Attack:null;if(attack){EditorGUILayout.Space();EditorGUILayout.LabelField("当前已获得",attack.Level(card.kind)+" / "+card.maxPicks);using(new EditorGUI.DisabledScope(attack.Level(card.kind)==0))if(GUILayout.Button("调试：减少此卡一次"))attack.Remove(card.kind);using(new EditorGUI.DisabledScope(!attack.Available(card)))if(GUILayout.Button("调试：获取此卡一次"))attack.Grant(card);}}
 }
 void DrawCharge(){Draw("chargeBaseTimes","基础蓄力三档时间（秒）");Draw("chargeUpgradeTimes","升级蓄力三档时间（秒）");Draw("chargeDamage","三档伤害（%攻击力）");EditorGUILayout.HelpBox("蓄力期间不可移动且不普攻；松手或蓄满释放。",MessageType.Info);}
 void DrawSword(){Draw("values","伤害（%攻击力）");Draw("cooldown","充能恢复时间（秒，0沿用技能配置）");var arena=Card.GetComponentInParent<ArenaPrototype>();if(arena&&arena.v06Skills){var settings=new SerializedObject(arena.v06Skills);settings.Update();if(Card.kind==V06CardKind.月牙){EditorGUILayout.PropertyField(settings.FindProperty("moonHitFollowsVisual"));if(!settings.FindProperty("moonHitFollowsVisual").boolValue)EditorGUILayout.PropertyField(settings.FindProperty("moonHitWidth"),new GUIContent("手动命中总宽度"));EditorGUILayout.LabelField("当前命中总宽度",arena.v06Skills.EffectiveMoonHitWidth.ToString("0.##"));}EditorGUILayout.PropertyField(settings.FindProperty("swordSpeed"));EditorGUILayout.PropertyField(settings.FindProperty("swordRange"));settings.ApplyModifiedProperties();var set=arena.v06Skills.animationSet;if(set)EditorGUILayout.ObjectField("外观配置（点击查看图片尺寸）",set,typeof(SkillAnimationSet),false);}EditorGUILayout.HelpBox("飞行速度和距离由两种剑气共用。开启同步后，月牙命中宽度等于动画显示高度×倍率；不使用副参数、持续时间或范围覆盖。",MessageType.Info);}
 void DrawDance(){var arena=Card.GetComponentInParent<ArenaPrototype>();var build=arena&&arena.v06Attack?arena.v06Attack.build:null;if(!build){EditorGUILayout.HelpBox("请绑定构筑规则组件",MessageType.Warning);return;}var settings=new SerializedObject(build);settings.Update();foreach(var field in new[]{"danceMovePercentPerStack","danceAttackPercentPerStack","danceStackLimit","danceMissTimeout"})EditorGUILayout.PropertyField(settings.FindProperty(field));settings.ApplyModifiedProperties();if(Application.isPlaying){EditorGUILayout.LabelField("当前叠层",build.DanceStacks.ToString());EditorGUILayout.LabelField("未命中清层倒计时",build.DanceTimeRemaining.ToString("0.0")+" 秒");}EditorGUILayout.HelpBox("仅普攻命中生效，每轮叠一次，同轮后续命中刷新计时。斩、剑气和持续伤害不刷新。超过设定时间未命中或实际扣生命后清空。",MessageType.Info);}
 void DrawAfterimage(){var values=serializedObject.FindProperty("values");if(values.arraySize>0)EditorGUILayout.PropertyField(values.GetArrayElementAtIndex(0),new GUIContent("爆炸伤害（%攻击力）"));Draw("cooldown","独立冷却（0沿用默认）");Draw("duration","存续时间（秒，0默认3）");Draw("radius","爆炸半径（0默认3）");var arena=Card.GetComponentInParent<ArenaPrototype>();if(arena&&arena.v06Skills){var settings=new SerializedObject(arena.v06Skills);settings.Update();EditorGUILayout.PropertyField(settings.FindProperty("afterimageTint"),new GUIContent("残影颜色"));EditorGUILayout.PropertyField(settings.FindProperty("afterimageAttractRadius"),new GUIContent("吸引敌人半径"));settings.ApplyModifiedProperties();}EditorGUILayout.HelpBox("按下闪立即在原地留下暗色玩家残影，不要求极限闪避。附近敌人优先攻击残影；受到一次攻击或存续到期后爆炸。",MessageType.Info);}
 void DrawWriting(){var values=serializedObject.FindProperty("values");if(values.arraySize>0)EditorGUILayout.PropertyField(values.GetArrayElementAtIndex(0),new GUIContent("写意持续时间（秒）","开启后持续多久；例如5表示5秒"));else{EditorGUILayout.HelpBox("尚未设置持续时间",MessageType.Warning);if(GUILayout.Button("设置5秒")){values.arraySize=1;values.GetArrayElementAtIndex(0).floatValue=5;}}
 var arena=Card.GetComponentInParent<ArenaPrototype>();var skills=arena?arena.v06Skills:null;if(skills){var settings=new SerializedObject(skills);settings.Update();EditorGUILayout.PropertyField(settings.FindProperty("writingAttackSpeed"),new GUIContent("期间攻速加成（%）","70表示临时增加70%攻击速度，用于自动普攻节奏"));EditorGUILayout.PropertyField(settings.FindProperty("writingHaste"),new GUIContent("期间技能急速（点）","60表示增加60点急速；冷却按基础冷却÷(1+急速/100)计算"));EditorGUILayout.PropertyField(settings.FindProperty("writingMoveSpeed"),new GUIContent("期间移速加成（%）","例如20表示写意期间移动速度提高20%，退出状态立即移除"));settings.ApplyModifiedProperties();EditorGUILayout.LabelField("长按闪基础冷却",skills.sprintCD.ToString("0.##")+" 秒");}
 EditorGUILayout.HelpBox("长按闪开启，松手继续。期间自动斩不占用斩按钮冷却；点击斩立即退出并释放正常伤害手动斩，点击闪直接退出。普攻、自动斩及触发的月牙伤害为50%。状态结束后开始长按闪冷却，基础冷却×1.5，再计算技能急速。",MessageType.Info);
 }
 void Draw(string name,string label)=>EditorGUILayout.PropertyField(serializedObject.FindProperty(name),new GUIContent(label),true);
}
